entries[446344] = { ["name"] = "Klebriges Netz", ["text"] = "300 Meter Reichweite\nSofort\nBrutverderber Ovi'nax überzieht mehrere Spielercharaktere mit klebrigem Gespinst, verursacht alle 0.5 Sek. 460505 Naturschaden und verringert die Bewegungsgeschwindigkeit bis zur Bannung um 70%.\n\nBei Entfernen wird eine ' Gespinsteruption ' ausgelöst." }
