entries[446598] = { ["name"] = "Hammer der Reinheit", ["text"] = "Wirken in 2 sek.\nBraunspyß ruft sengendes Licht auf die Position eines Spielercharakters herab und fügt Spielercharakteren innerhalb von 3 Metern 7272815 Heiligschaden zu. Die Hämmer drehen sich dann spiralförmig vom Einschlagsort aus nach außen und fügen Spielercharakteren auf ihrem Weg 7272815 Heiligschaden zu.\n\nWährend Ermächtigung durch ' Rachsüchtige Wut ' trifft ' Hammer der Reinheit ' 5 Spielercharaktere." }
