entries[446615] = { ["name"] = "Verstärkung heranführen", ["text"] = "Wirken in 2 sek.\nBringt weitere Mitglieder des Ordens der Nacht hervor, die den Zaubernden 2 Sek. lang im Kampf unterstützen. Diese beginnen mit verringerter Gesundheit, wobei ' Verstärkung heranführen ' die fehlende Gesundheit mit der Zeit heilt.\n\nDiese Einheiten sind mit ' Schnellbeschwörung ' belegt.\n\nSchnellbeschwörung\nBeeinträchtigt durch Schnellbeschwörung, reduziert verursachten Schaden um 80% und Gesundheit um 70%." }
