entries[446648] = { ["name"] = "Glutbräukrug", ["text"] = "Ca. 2 Procs pro Minute\nTeilt gelegentlich ein Getränk mit Verbündeten, die Euch im Kampf beistehen, das ihnen 15 Sek. lang 48 ihres Primärwertes gewährt und 951 Schaden absorbiert. Auch Ihr nehmt einen Schluck, der 26 Hauptwert gewährt und 4882 Schaden absorbiert.\n\nWenn Eure Gesundheit unter 50% fällt, nehmt Ihr einen Notfallschluck. Dies kann nur einmal alle 1 Min. geschehen.\n\nGilt nur für Tankspezialisierungen." }
entries[446649] = { ["name"] = "Schild des Züchtigers", ["text"] = "300 Meter Reichweite\nWirken in 1 sek.\nBraunspyß schleudert einen heiligen Schild auf mehrere Spielercharaktere, der ihnen 3527308 Heiligschaden zufügt und ihre Bewegungsgeschwindigkeit 5 Sek. lang um 50% verringert.\n\nWährend Ermächtigung durch ' Rachsüchtige Wut ' trifft ' Schild des Züchtigers ' 5 Spielercharaktere." }
