entries[447034] = { ["name"] = "Säule der Macht", ["text"] = "100 Meter Reichweite\nSofort\nGeneral Umbriss stampft auf den Boden und lässt 2 Min. lang mehrere Exemplare von ' Säule der Macht ' ausbrechen, was Spielercharakteren innerhalb von 6 Metern 20 Schaden zufügt und sie zurückstößt.\n\n' Säule der Macht ' fügt Spielercharakteren im Effektbereich alle 1 Sek. 10 körperlichen Schaden zu.\n\nWenn eine Säule der Macht zerstört wird, werden 'Zerschmetterte Felsen' fortgeschleudert." }
