entries[447174] = { ["name"] = "Todesumhang", ["text"] = "Unbegrenzte Reichweite\nSofort\nKy'veza verschlingt ' Todesmasken ' von Netherphantomen, die während ' Zwielichtmassaker ' durch sie hindurchrasen, und hüllt sich für 12 Sek. in deren dunkle Macht. Solange dieser Effekt aktiv ist, ist Ky'vezas Schaden um 10% erhöht. Dieser Effekt ist stapelbar.\n\nBeim Erreichen von 3 Stapeln wird ' Todesumhang ' zu einem dauerhaften Effekt." }
