entries[447176] = { ["name"] = "Türkisfarbene Glühmilbe", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Glühmilben sind in den Schallenden Tiefen als erstaunlich robuste Reittiere bekannt. Diese Art gibt ein weiches, cyanblaues Leuchten von sich, dass die Kobolde besonders entspannend finden.\"\nVerkäufer:\nWachshändler Squick\nZone:\nSchallende Tiefen\nKosten:\n11.375" }
