entries[447180] = { ["name"] = "Erstickende Stränge", ["text"] = "40 Meter Reichweite\nSofort\nDer Zaubernde erfüllt die Luft und damit auch die Lungen seines Ziels mit nahezu unsichtbaren Spinnweben, was das Ziel verwundbar macht. Das Ziel erleidet mit der Zeit immer mehr Schaden.\n\nDieser Effekt ist stapelbar." }
