entries[447189] = { ["name"] = "Nistende Schwärmilbe", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Als natürliche Gräber lauern sie oft in kleinen Tierbauten, wenn sie Eier legen oder größere Beute überraschen wollen.\"\nZone:\nVision von Sturmwind (Neuerlebt)\nZone:\nVision von Orgrimmar (Neuerlebt)" }
entries[447190] = { ["name"] = "Schattenhafte Schwärmilbe", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Schwärmilben trifft man in der Wildnis von Azj-Kahet häufig an, dazu findet man sie bei den Nerubern, die sie seit Langem zähmen, wodurch sie für unvorsichtige Abenteurer aber nicht weniger gefährlich sind.\"\nErfolg:\nRuhm des Nerub'ar-Plünderers\nKategorie:\nDungeons & Schlachtzüge" }
