entries[447332] = { ["name"] = "Bismutbetriebenes Samophlang", ["text"] = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHandvoll Bismutbolzen (8), Launische Verdrahtung (2), Kreisende Ausrüstung (2)\nOptionale Reagenzien:\nErsatzteile (#376) , Authentizität des Kunsthandwerks (#346) , Herstellungswerte anpassen (#352)\nBerufsausbilder:\nIngenieurskunst von Khaz Algar (10)\nKosten:\n110\n\nBismutbetriebenes Samophlang\nWird beim Anlegen gebunden\nWerkzeug für Ingenieurskunst\n+ 132 Zufallswert 1\nAnlegen: +8 Fertigkeit in Ingenieurskunst von Khaz Algar\n68\n\"Ein unnötig kompliziertes Allzweckwerkzeug, heiß begehrt bei allen ambitionierten Ingenieuren.\"" }
entries[447333] = { ["name"] = "Aqiritbetriebenes Samophlang", ["text"] = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHändchen fürs Kunsthandwerk (300), Handvoll Bismutbolzen (64), Launische Verdrahtung (8), Kreisende Ausrüstung (16), Sicherheitsschalter (2), Entropieverstärker (4)\nOptionale Reagenzien:\nErsatzteile (#376) , Authentizität des Kunsthandwerks (#346) , Herstellungswerte anpassen (#352)\nSpezialisierung:\nDurch Ingenieurskunst hergestellte Ausrüstung (40)\n\nAqiritbetriebenes Samophlang\nWird beim Aufheben gebunden\nWerkzeug für Ingenieurskunst\n+ 100 Zufallswert 1\nAnlegen: +18 Fertigkeit in Ingenieurskunst von Khaz Algar\n68\n\"Ein unnötig kompliziertes Allzweckwerkzeug, heiß begehrt bei allen ambitionierten Ingenieuren.\"" }
