entries[447335] = { ["name"] = "Aqiritvorrat des Minenarbeiters", ["text"] = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHändchen fürs Kunsthandwerk (300), Aqirit (60), Handvoll Bismutbolzen (24), Launische Verdrahtung (8), Kreisende Ausrüstung (12), Entropieverstärker (3)\nOptionale Reagenzien:\nErsatzteile (#376) , Authentizität des Kunsthandwerks (#346)\nEntdeckung:\nVerständlich geordnete Ideen\nVoraussetzungen:\nSpezialisierung - Berufsausrüstung\n\nAqiritvorrat des Minenarbeiters\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Rücken (1)Zubehör für Bergbau\n+ 121 Finesse\nAnlegen: +11 Fertigkeit in Bergbau von Khaz Algar\n68" }
entries[447352] = { ["name"] = "W.U.M.M.S. x2", ["text"] = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHandvoll Bismutbolzen (64), Launische Verdrahtung (18), Kreisende Ausrüstung (12), Sicherheitsschalter (4), Chaosschaltkreis (2), Funke (#256) (2)\nOptionale Reagenzien:\nSekundärwerte anpassen (#283) , Verzierung hinzufügen (#340) , Mit Energie erfüllen (#284) , Ersatzteile (#376) , Authentizität des Kunsthandwerks (#346) , Weiter Augmentieren (#384)\nSpezialisierung:\nDurch Ingenieurskunst hergestellte Ausrüstung - Schusswaffen\n\nW.U.M.M.S. x2\nWird beim Aufheben gebunden\nDistanz Schusswaffe\n3,365 - 6,251 Schaden Geschwindigkeit 3.00\n(1,603 Schaden pro Sekunde)\n+2.129 Beweglichkeit\n+9.748 Ausdauer\n+ 728 Zufallswert 1\n+ 728 Zufallswert 2\nHaltbarkeit 120 / 120\n58\n\"Komm schon, schieß schneller!\"" }
entries[447364] = { ["name"] = "Unwiderstehlicher roter Knopf", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (10), Handvoll Bismutbolzen (12), Launische Verdrahtung (3), Kreisende Ausrüstung (4), Entropieverstärker\nOptionale Reagenzien:\nErsatzteile (#347) , Authentizität des Kunsthandwerks (#346)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\nUnwiderstehlicher roter Knopf\nWird beim Aufheben gebunden\nBenutzen: Setzt ein Gerät ein, das von Euch oder einem Mitglied Eurer Gruppe bzw. Eures Schlachtzugs aktiviert werden kann, wenn eine Notlage droht. Wenn es aktiviert wird, versucht es, am Ende des Kampfes alle Verbündeten in der Nähe wiederzubeleben.\n\nHält 1 Stunde lang an oder bis es aktiviert wird. Muss vor dem Kampf eingesetzt werden.\n68\nBenötigt Ingenieurskunst von Khaz Algar\n(1)" }
entries[447365] = { ["name"] = "Pausierender Pylon", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (10), Handvoll Bismutbolzen (8), Launische Verdrahtung (2), Kreisende Ausrüstung (2)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\nBenutzen: Platziert einen pausierenden Pylonen, der die Stoffwechselprozesse von Spielercharakteren in seiner Nähe unterbricht und den Ablauf der Fläschchen, Phiolen und Sättigungseffekte von Khaz Algar anhält.\n\nDer Pylon ist äußert zerbrechlich und explodiert in der Gegenwart von Gewalt.\n68" }
entries[447367] = { ["name"] = "Algarischer Reparaturbot 11-O", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (10), Handvoll Bismutbolzen (8), Launische Verdrahtung , Kreisende Ausrüstung (2), Entropieverstärker\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\nAlgarischer Reparaturbot 11-O\nWird beim Aufheben gebunden\nBenutzen: Setzt einen kleinen irdenen Golem ein, der Euch und Euren Gefährten erlaubt, Eure Ausrüstung zu reparieren.\n\nHält 10 Min. lang an.\n68\nBenötigt Ingenieurskunst von Khaz Algar\n(1)" }
entries[447368] = { ["name"] = "Tragbarer Berufsmöglichkeitenprojektor", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (10), Handvoll Bismutbolzen (12), Launische Verdrahtung , Kreisende Ausrüstung (2), Entropieverstärker\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\nTragbarer Berufsmöglichkeitenprojektor\nBenutzen: Beschwört einen Möglichkeitenprojektor, der für die Erfüllung der Anforderungen an Handwerkstische konfiguriert wurde. Es kann nur eine Werkbank gleichzeitig angezeigt und ausschließlich durch den Ingenieur ausgetauscht werden. (10 Min Abklingzeit)\n68\nBenötigt Ingenieurskunst von Khaz Algar\n(1)" }
entries[447369] = { ["name"] = "Fass mit Feuerwerkskörpern", ["text"] = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (50), Launische Verdrahtung (24), Kreisende Ausrüstung (10), Chaosschaltkreis (8), Entropieverstärker (3)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\nFass mit Feuerwerkskörpern\nSpielzeug\nBenutzen: Stellt ein gefährliches Fass mit Feuerwerkskörpern auf, das 5 Min. Sek. lang stehen bleibt, um für Euch und Eure Freunde den Nachthimmel grell zu erleuchten!\n\nAndere Spielercharaktere können sich das Feuerwerk auch ansehen, indem sie das Fass angreifen.\n\nWährend der Feierlichkeiten von betrunkenen Goblins ist die Abklingzeit verringert. (1 Stunde Abklingzeit)" }
entries[447370] = { ["name"] = "Defekte Rettungskapsel", ["text"] = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (75), Launische Verdrahtung (10), Kreisende Ausrüstung (16), Sicherheitsschalter (6), Entropieverstärker (2)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\nDefekte Rettungskapsel\nSpielzeug\nBenutzen: Sucht dringend Schutz in einer defekten Rettungskapsel. Ihr kommt zwar nicht sehr weit, doch dafür seid Ihr in Sicherheit. (10 Min Abklingzeit)" }
entries[447371] = { ["name"] = "Filmlose Kamera", ["text"] = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (100), Launische Verdrahtung (6), Kreisende Ausrüstung (8), Sicherheitsschalter , Entropieverstärker\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\nFilmlose Kamera\nSpielzeug\nBenutzen: Weckt Euer Fotografietalent! (30 Sek. Abklingzeit)" }
entries[447372] = { ["name"] = "Wurmlochgenerator: Khaz Algar", ["text"] = "Wirken in 2 sek. 2\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (125), Launische Verdrahtung (8), Kreisende Ausrüstung (16), Chaosschaltkreis (4), Entropieverstärker (4)\nEntdeckung:\nErfinden, Prototypenerstellung und Notizen\n\nWurmlochgenerator: Khaz Algar\nSpielzeug\nBenutzen: Öffnet ein Wurmloch, das es dem Benutzer ermöglicht, schnell an einen zufälligen Ort in Khaz Algar zu reisen. (30 Min Abklingzeit)\n68\nBenötigt Ingenieurskunst von Khaz Algar\n(1)" }
entries[447373] = { ["name"] = "Meuteverprügler 2-30", ["text"] = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFülle an Bolzen (1000), Sortierte Kurbelwurbeln (200), Blinkerflüssigkeit (80), Kataklysmischer Konverter (50), Prügelsichere Platten (20), Prügelerlaubnis\nDie erforderlichen Komponenten können von Paxton Bombenhülse an der Chancenspitze erworben werden.\n\nIhr könnt diese Teile manchmal finden, wenn Ihr ' Teile durchkramen ' einsetzt.\nEntdeckung:\nVerständlich geordnete Ideen\n\nMeuteverprügler 2-30\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man den Meuteverprügler 2-30 beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Schlägt Euren Gegnern mit einem einzigen Hieb die Zähne aus. Garantiert!\"\nBeruf:\nIngenieurskunst von Khaz Algar" }
