entries[447393] = { ["name"] = "Renos zufällige Reaktionen", ["text"] = "Animabonus\nSofort\nBeim Angreifen besteht eine Chance, einen zufälligen Gegenstand aus Renos Rucksack zu werfen. Der Gegenstand kann den Gegner und seine nahen Verbündeten festwurzeln, betäuben oder ihnen Schaden zufügen.\n(Procchance: 10%, 1Min. Abklingzeit)" }
entries[447395] = { ["name"] = "Flammendes Spalten", ["text"] = "Wirken in 3 sek.\nThrongus spaltet seine Gegner mit einer geschmolzenen Axt, wodurch Spielercharaktere vor ihm 12130320 körperlichen Schaden erleiden." }
entries[447396] = { ["name"] = "Blitzstaub", ["text"] = "40 Meter Reichweite\nSofort\nEure Angriffe habe eine Chance, einen Blitzschlag abzufeuern, der Eurem Ziel (100% der Zaubermacht) Naturschaden zufügt." }
entries[447399] = { ["name"] = "Wachschwarm", ["text"] = "Unbegrenzte Reichweite\nSofort\nDieser Schwarm kontrolliert die unmittelbare Umgebung und zerfetzt jeden, der sie zu betreten wagt. Verursacht bei Kontakt alle 0.5 Sek. Naturschaden in Höhe von 10% der Gesundheit des Ziels." }
entries[447400] = { ["name"] = "Seuchenschlund", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nKönigin Rickiticka beißt nach ihrem aktuellen Ziel, verursacht 8 Naturschaden und verseucht das Ziel mit Spinnen, die alle 3 Sek. weitere 6 Schaden verursachen. Wenn der Befall ausläuft, brechen drei Brutlinge aus dem Ziel hervor." }
entries[447401] = { ["name"] = "Flüssiges Metall", ["text"] = "Unbegrenzte Reichweite\nSofort\nInflicts 10 Fire damage to an enemy every 1 sec for 5 Min.." }
