entries[447425] = { ["name"] = "Kettenblitzschlag", ["text"] = "100 Meter Reichweite\nSofort\nSchleudert einen Blitzschlag auf den Gegner, der (382.582% der Zaubermacht) Naturschaden verursacht und dann auf weitere Gegner in der Nähe überspringt. Wirkt auf insgesamt 3 Ziele." }
