entries[447429] = { ["name"] = "Wildes Zerfleischen", ["text"] = "100 Energie\nSofort 5 sek. Abklingzeit\nHauptmann Talschrei befiehlt Funke, einen Spielercharakter zu zerfleischen, was diesen bewegungsunfähig macht und ihm alle 0.5 Sek. 848557 körperlichen Schaden zufügt.\n\nHauptmann Talschrei beschützt Funke, während er sein Ziel zerfleischt, und absorbiert die nächsten 24906168 Schaden. Wenn Talschreis Schutz durchbrochen wird, unterbricht das den Effekt." }
entries[447433] = { ["name"] = "Kettenheilung", ["text"] = "100 Meter Reichweite\nSofort\nHeilt das verbündete Ziel um (187% der Zaubermacht) Gesundheit und springt dann bis zu 15 Meter auf die 2 am schwersten verwundeten Verbündeten in der Nähe über, um sie zu heilen. Mit jedem Sprung verringert sich die Heilung um 30%." }
