entries[447444] = { ["name"] = "Entropischer Riss", ["text"] = "Disziplin\nBeim Einsatz von 'Gedankenschlag' entsteht ein 'Entropischer Riss', der den Gegner 8 Sek. lang verfolgt. Gegner, die in seinen Pfad geraten, erleiden alle 1 Sek. (60% der Zaubermacht) Schattenschaden, solange sie in Reichweite sind.\n\nSchatten\nBeim Einsatz von 'Leerenstrom' entsteht ein 'Entropischer Riss', der den Gegner 8 Sek. lang verfolgt. Gegner, die in seinen Pfad geraten, erleiden alle 1 Sek. (60% der Zaubermacht) Schattenschaden, solange sie in Reichweite sind." }
