entries[447513] = { ["name"] = "Demoliert", ["text"] = "40 Meter Reichweite\nSofort\n'Kolossale Macht' ist bis zu 10-mal stapelbar. Wenn Ihr bei maximalen Stapeln sonst einen Stapel 'Kolossale Macht' erhalten würdet, verringert sich die Abklingzeit von 'Demolieren' um 2 Sek.\n\nVon 'Demolieren' betroffene Gegner erleiden bis zu 10% mehr Schaden durch Euch und fügen Euch bis zu 10% weniger Schaden zu, abhängig davon, wie viele Stapel 'Kolossale Macht' von 'Demolieren' verbraucht wurden. Hält 10 Sek. lang an." }
