entries[447592] = { ["name"] = "Bollwerk des Schwarzen Ochsen", ["text"] = "Kanalisiert das Bollwerk des Schwarzen Ochsen. Stürmt auf einen Gegner zu und entfernt alle Betäubungs- und Bewegungsunfähigkeitseffekte, erhaltet einen 74612 Schaden absorbierenden Schild und verspottet Gegner innerhalb von 20 Metern. Fügt Gegnern innerhalb von 20 Metern 5 Sek. lang alle 1 Sekunden 3638 körperlichen Schaden plus 20% des vom Schild erlittenen Schadens zu." }
