entries[447867] = { ["name"] = "Kah, König der Tiefen", ["text"] = "Wirken in 3.2 sek.\nVom Blut der Alten Götter verzerrt, spannt sich seine kränkliche, blasse Haut über seinen skelettartigen Körper. Angler in ganz Khaz Algar bezeichnen diesen Fisch als einen Boten der Verdammnis, der jeden Angler verflucht, der das Pech hat, ihn an Land zu ziehen. Wenn man dieser Kreatur in die Augen schaut, wird ihre Verdorbenheit nur noch umfassender, denn jedes Spiegelbild wird vom Abgrund verschlungen." }
entries[447868] = { ["name"] = "Algarische Inschriftenkundeabhandlung", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nLeylinienrückstände (2), Unbändige Chiffre , Sonnige Tinte (2)\nSpezialisierung:\nStreben nach Wissen\n\nAlgarische Inschriftenkundeabhandlung\nWird an Kriegsmeute gebunden\nBenutzen: Studieren, um Euer Inschriftenkundewissen von Khaz Algar um 1 zu erhöhen. (5 Sek. Abklingzeit)\nBenötigt Inschriftenkunde von Khaz Algar\n(25)" }
entries[447869] = { ["name"] = "Feines Eierpulver", ["text"] = "Wirken in 2 sek.\nRezept für 5 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nPolo\nZone:\nStadt der Fäden\nKosten:\n1500" }
entries[447870] = { ["name"] = "Alles-am-Stock", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGeronnenes Eigelb\nRezept für 2 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nWelthändler von Khaz Algar\nKosten:\n1.500" }
entries[447871] = { ["name"] = "Proteinschlabber", ["text"] = "Wirken in 2 sek.\nReagenzien:\nFeines Eierpulver (5)\nRezept für 1 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\n\"Achtfachschüttlerin\" Blass\nZone:\nStadt der Fäden\nKosten:\n1500" }
entries[447872] = { ["name"] = "Schwammschlemmerei", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers , Feines Eierpulver (10)\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 1 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nPolo\nZone:\nStadt der Fäden\nKosten:\n1500\n\nSchwammschlemmerei\nBenutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und Euer niedrigster Sekundärwert wird 15 Min. lang um [Quellwert] erhöht.\n68", ["unresolvedValues"] = true }
entries[447873] = { ["name"] = "Geheimsoße", ["text"] = "Wirken in 2 sek.\nReagenzien:\nFeines Eierpulver (5), Geronnenes Eigelb , Trinkschlauch des Tiefenforschers\nRezept für 1 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nEntdeckung:\nVorbereitete Zutaten - Feines Eierpulver\n\nGeheimsoße\n68" }
entries[447874] = { ["name"] = "Kleine Kumpelkekse", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGeronnenes Eigelb , Schwammschlemmerei (4), Klumpiges Mehl (5)\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nTyro Whalekk\nZone:\nStadt der Fäden\nKosten:\n1500\n\nKleine Kumpelkekse\nBenutzen: Belebt alle Eure Haustiere wieder und heilt sie auf 100% Gesundheit.\n68\n\"Aus echten kleinen Kumpeln!\"" }
entries[447875] = { ["name"] = "Azj-Kahet-Spezial", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTrinkschlauch des Tiefenforschers , Geronnenes Eigelb\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 1 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nAx'ill\nZone:\nStadt der Fäden\nKosten:\n1500\n\nVerkäufer:\nTej die Unverwüstliche\nZone:\nStadt der Fäden\nKosten:\n1.500\n\nAzj-Kahet-Spezial\nBenutzen: Erhöht Eure Bewegungsgeschwindigkeit um 20%, während Ihr in der Stadt der Fäden seid. Kann nur im Freien eingesetzt werden.\n68\n\"Stadtschlemmerei!\"" }
entries[447876] = { ["name"] = "Geisterfisch-Schmaus", ["text"] = "Wirken in 2 sek.\nReagenzien:\nVorbereiteter Geisterfisch , Einfacher Eintopf\nOptionale Reagenzien:\nGeheimzutat (#318)\nRezept für 5 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nVerkäufer:\nKapitänin Oathmyt\nZone:\nHeilsturz\nKosten:\n10\n\nGeisterfisch-Schmaus\nWird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und erhaltet 1 Stunde lang 30 Angelfertigkeit von Khaz Algar und 150 Wahrnehmung.\n75\n\"Der schlimmste Alptraum des Anglers ist die Delikatesse des Kochs.\"" }
