entries[447954] = { ["name"] = "Exterminieren", ["text"] = "Sofort\nFrost\nNachdem 'Mal des Schnitters' explodiert, kosten Eure nächsten [Quellwert] Einsätze von 1 [Quellwert]:Runen;; und beschwört 2 Sensen, die Eure Gegner trifft:treffen;.\n\nDie erste Sense fügt Eurem Ziel (407.975% der Angriffskraft) Schattenfrostschaden zu und hat eine Chance von 100%, eine 'Tötungsmaschine' zu gewähren. Die zweite Sense fügt allen Gegnern um Euer Ziel für (178.723% der Angriffskraft) Schattenfrostschaden zu [und belegt sie mit 'Frostfieber']. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nBlut\nNachdem 'Mal des Schnitters' explodiert, kosten Eure nächsten [Quellwert] Einsätze von 1 [Quellwert]:Runen;; und beschwört 2 Sensen, die Eure Gegner trifft:treffen;.\n\nDie erste Sense fügt Eurem Ziel (349.069% der Angriffskraft) Schattenfrostschaden zu und hat eine Chance von 100%, lang 2.0 Sek. einen 'Knochensturm' zu ernten. Die zweite Sense fügt allen Gegnern um Euer Ziel für (186.17% der Angriffskraft) Schattenfrostschaden zu [und belegt sie mit 'Frostfieber']. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n(1s Abklingzeit)", ["unresolvedValues"] = true }
